\chapter{Das Behalten: Kalender, Feste und das Gedenken}
% =====================================================================

\section{Der Kalender der Nachbarschaft}

\subsection{Kalender bauen und führen}

\begin{enumerate}
  \item Zeichne ein Jahres-Rad auf Brettfurnier (600 mm Durchmesser): 12 Sektoren (Monate), außen 365 Striche, außen die Sonne-Höhe (Band 8).
  \item Trage feste Termine ein: Rats-Sonntag (erster im Monat), Inventur (Quartals-Ende), Furt-Messung (monatlich), Waage-Eichung (30 Tage), Feuerprobe (Jahres-Ende).
  \item Hänge das Rad im Zeug-Haus oder am Brunnen; daneben die Schreib-Tafel für den laufenden Monat.
  \item Führe die Tafel täglich: Wer, was, Termin; erledigte Zeilen streichen.
  \item Prüfe am Jahres-Ende: Welche Fristen wurden nie gehalten? Diese ins Prüfbuch als Zeile.
\end{enumerate}

\begin{tabular}{@{}p{22mm}p{44mm}p{26mm}p{26mm}@{}}
\toprule
\textbf{Rhythmus} & \textbf{Fest-Termine der Reihe} & \textbf{Stadt} & \textbf{Land} \\
\midrule
täglich & Wache-Runde, Tafel-Zeilen & Wache & Hof-Gemeinschaft \\
wöchentlich & Zeug-Haus-Rundgang, Ofen-Reinigung & Werkstattwart & Werkstattwart \\
monatlich & Rat, Waage-Eichung, Furt-Messung & Rat & Rat der Höfe \\
quartalsweise & Inventur, Karte-Prüfung & Lagerwart & Lagerwart \\
jährlich & Feuerprobe, Fest, Gedenken & Gemeinschaft & Nachbarschaft \\
\bottomrule
\end{tabular}

\begin{konzept}{8.1}{Kalender}
\textbf{Definition.} Der Kalender ist die öffentliche Fristen-Ordnung der Nachbarschaft: Rad, Tafel und Einträge. Ohne Kalender wird jede Frist zur Meinung.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Hängt das Kalender-Rad öffentlich und ist die Monatstafel täglich beschrieben?
  \item Stehen alle Fristen der Bücher (Tausch, Zeug, Prüfung) als Termine im Rad?
  \item Wird am Jahres-Ende die Fristen-Treue geprüft?
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Kein wiederkehrender Termin wurde im letzten Quartal ohne Ersatz verschoben.
  \item Die Tafel zeigt keine überfällige Zeile über 3 Tage.
  \item Die Fristen-Treue des Jahres liegt über 90 Prozent (Zeilen-Prüfung).
\end{enumerate}

\textbf{Ehrliche Grenzen.} Der Kalender kennt keine Schaltregeln und keine Monatsnamen anderer; er zählt Tage ab einem Fest (Kapitel 8.2). Über Jahre hinweg verschiebt sich das Rad um wenige Tage gegen die Sonnen-Wende – örtlich prüfen und einmal je Jahr nachjustieren.
\end{konzept}

\section{Feste: das Jahr gliedern}

\subsection{Vier Feste im Jahres-Rad}

\begin{enumerate}
  \item Saat-Fest (Frühjahr, nach der letzten Boden-Frost-Nacht): gemeinsames Brot aus dem letzten Wintervorrat; Pause von 24 Stunden; Planung der Saat im Rat.
  \item Ernte-Fest (Herbst, nach dem letzten Getreide-Eintrag): gemeinsames Mahl, Verteil-Regeln beschließen, Dank an die Amtsträger aussprechen.
  \item Licht-Fest (Winter, tiefste Sonne-Steht-Zeit): Öl- und Kerzen-Gemeinschaft, Erzählen der Jahres-Zeilen, keine Arbeit nach Einbruch.
  \item Gedenk-Fest (Jahres-Ende): Namen der Verstorbenen und der Neugeborenen, ein Satz je Person, Eintrag im Vermächtnis (Kapitel 9).
\end{enumerate}

\begin{tabular}{@{}p{22mm}p{30mm}p{30mm}p{26mm}@{}}
\toprule
\textbf{Fest} & \textbf{Stadt-Form} & \textbf{Land-Form} & \textbf{Material} \\
\midrule
Saat-Fest & Hof-Ofen, Brot teilen & Feld-Rand, Saat-Segen & Brot, Öl \\
Ernte-Fest & Marktplatz-Mahl & Tenn-Mahl & Getreide, Käse, Bier \\
Licht-Fest & Treppenhaus, Kerzen & Stube, Ofen & Kerzen, Öl, Holz \\
Gedenk-Fest & Brunnen, Namen & Fried-Hain oder Feldrand & Namen-Buch (Anhang A.8) \\
\bottomrule
\end{tabular}

\begin{baustein}
\textbf{Merksatz.} Ein Fest ohne Zeile ist eine Party; ein Fest mit Zeile ist ein Kalender-Punkt, der die Nachbarschaft zusammenhält.
\end{baustein}

\begin{konzept}{8.2}{Feste}
\textbf{Definition.} Feste sind befristete, wiederkehrende Gemeinschafts-Zeiten mit fester Ordnung (Ort, Mahl, Zeile); sie gliedern das Jahr und erneuern die Zugehörigkeit.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Haben alle vier Feste Ort, Mahl und Zeile im Kalender-Rad?
  \item Ist die Ordnung so knapp, dass sie ohne Wortführer wiederholbar ist?
  \item Verzehrt das Fest nur Überschüsse, keine Vorrats-Reserve (Faustwert: unter 5 Prozent des Monats-Vorrats)?
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Alle vier Feste des Jahres wurden gehalten.
  \item Kein Fest griff auf die 90-Tage-Reserve (Konzept 1.2) zu.
  \item Die Feste endeten ohne Streit und mit vollzähligem Namen-Buch.
\end{enumerate}

\textbf{Ehrliche Grenzen.} Feste halten, was Arbeitsteilung hält: In einer zerstrittenen Nachbarschaft wird das Fest zur Pflicht-Veranstaltung und wirkt dann umgekehrt. Erst Streit-Verfahren (Konzept 4.4), dann Fest.
\end{konzept}

\section{Das Gedenken: Namen-Buch}

\subsection{Namen-Buch führen}

\begin{enumerate}
  \item Nimm ein fest gebundenes Buch (60 Blatt) als Namen-Buch (Anhang A.8).
  \item Trage je Person eine Zeile ein: Name, Ankunft (Datum, Ort), Fertigkeit, Amt, Abschied.
  \item Trage bei Verstorbenen: Datum, Ursache (kurz, ohne Deutung), Erbe der Werkzeuge (Zeug-Buch-Zeile).
  \item Lies beim Gedenk-Fest je Verstorbenem und Neugeborenem einen Satz vor; die Zeile bleibt.
  \item Bewahre das Namen-Buch im Zeug-Haus, Regal 3; es ist Gemeingut.
\end{enumerate}

\begin{konzept}{8.3}{Gedenken}
\textbf{Definition.} Das Gedenken ist die öffentliche Zeilen-Haltung über Personen: Ankunft, Fertigkeit, Amt, Abschied. Es ersetzt Register, die ohne Ordnung niemand führt.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Hat jede Person der Nachbarschaft eine Zeile mit Ankunft und Fertigkeit?
  \item Wird das Buch beim Gedenk-Fest vorgelesen?
  \item Liegt das Buch im Zeug-Haus, nicht in einer Privatwohnung?
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Das Buch ist vollständig (Stichprobe mit dem Amt-Buch abgeglichen).
  \item Verstorbene haben Zeilen mit Datum und Werkzeug-Erbe.
  \item Das Gedenk-Fest wurde ohne Ausfall gehalten.
\end{enumerate}

\textbf{Ehrliche Grenzen.} Das Buch hält Namen, nicht Erinnerungen: Wer mehr will, schreibt es daneben – aber das Verfahren verlangt nur die Zeile. Gedenken ohne Zeile verkommt in der zweiten Generation zum Gerücht.
\end{konzept}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-8-1}
\caption{Abb. 8.1 – Das Jahres-Rad: zwölf Monate, vier Feste und die wiederkehrenden Rhythmen}
\end{figure}

\section{Kapitel-Checkliste: Kalender und Gedenken}
\begin{itemize}
  \item Das Jahres-Rad hängt öffentlich; die Monatstafel ist täglich beschrieben.
  \item Alle Fristen der Bücher stehen als Termine im Rad.
  \item Die Fristen-Treue des Jahres liegt über 90 Prozent.
  \item Alle vier Feste wurden gehalten, ohne die 90-Tage-Reserve anzugreifen.
  \item Das Namen-Buch enthält jede Person mit Ankunft, Fertigkeit und Amt.
  \item Das Gedenk-Fest wurde mit je einem Satz je Name gehalten.
\end{itemize}

