\chapter{Das Ende der Reihe: das Vermächtnis und der Schlussstein}
% =====================================================================

\section{Das Vermächtnis schreiben}

\subsection{Vermächtnis in acht Schritten}

\begin{enumerate}
  \item Sammle am Jahres-Ende: Prüfbuch (erledigte Zeilen), Tauschbuch (Summen je Ware), Amt-Buch (Beschlüsse), Namen-Buch (Zugänge und Abgänge).
  \item Schreibe auf 4 Seiten: Was wurde gebaut? Was wurde gelernt? Was ging schief (mit Messwert)? Was bleibt offen (mit Termin)?
  \item Schreibe je Abschnitt der Reihe einen Satz über den Stand (Band 3 Lager: Zustand; Band 9 Werkzeug: Bestand).
  \item Nenne die drei größten Verluste des Jahres mit Namen und Ursache, ohne Schuld-Zuweisung.
  \item Nenne die drei wichtigsten Gewinne des Jahres mit Messwert.
  \item Hinterlege das Vermächtnis im Zeug-Haus, Regal 3; zweite Abschrift im Namen-Buch-Umschlag.
  \item Lies das Vermächtnis beim ersten Rat des neuen Jahres laut vor; der Rat beschließt je offener Zeile einen Namen und Termin.
  \item Prüfe beim nächsten Jahres-Ende, welche Zeilen gehalten wurden; ungehaltene in das neue Vermächtnis als erste Zeilen.
\end{enumerate}

\begin{konzept}{9.1}{Vermächtnis}
\textbf{Definition.} Das Vermächtnis ist die jährliche, vierseitige Zusammenfassung aus Messwerten und offenen Terminen; es ist die Erinnerung der Nachbarschaft über Köpfe und Generationen hinweg.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Stehen Messwerte in den Zeilen, nicht Meinungen?
  \item Hat jede offene Zeile einen Termin und einen Namen?
  \item Liegen Original und Abschrift an zwei Orten?
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Das Vermächtnis wurde im Rat vorgelesen.
  \item Mindestens die Hälfte der offenen Zeilen des Vorjahres wurde gehalten.
  \item Das neue Vermächtnis nennt die ungehaltenen Zeilen als erste Einträge.
\end{enumerate}

\textbf{Ehrliche Grenzen.} Ein Vermächtnis ersetzt keine Übung und kein Verfahren; es sagt nur, was war. Wer sein Überleben auf Vermächtnisse statt auf geprüfte Verfahren stützt, sammelt Papier. Das Vermächtnis ist Schlussstein, nicht Fundament.
\end{konzept}

\section{Der Schlussstein der Reihe}

\begin{devise}
Was bleibt, ist nicht das Meiste, sondern das Wiederholbare:
eine Waage, die beide eicht, ein Rat, der Zeilen schreibt,
ein Buch, das fremde Hände lesen können.
\end{devise}

\section{Kapitel-Checkliste: Vermächtnis}
\begin{itemize}
  \item Das Vermächtnis des Jahres ist auf vier Seiten aus Messwerten geschrieben.
  \item Offene Zeilen haben Namen und Termine vom Rat.
  \item Original und Abschrift liegen an zwei Orten.
  \item Die offenen Zeilen des Vorjahres sind geprüft; ungehaltene stehen vorne.
\end{itemize}
